"""Generate numeric figure data and replacement scientific figures from this run."""
from pathlib import Path
import json
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results';FIG=ROOT/'figures';FIG.mkdir(exist_ok=True)
f=pd.read_csv(OUT/'FIGURE4_DATA.csv')
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False})
def panel(ax,group):
    d=f[f.candidate_group==group].set_index('background')
    vals=[100*d.iloc[0].recorded_key_fraction,100*d.loc['neutral','first_success_fraction'],100*d.loc['observed','first_success_fraction']]
    bars=ax.bar(['Recorded key\nturnover','Neutral\nbackground','Observed\nbackground'],vals,color=['#6a7886','#277c87','#b35e39'],width=.64)
    for b,v in zip(bars,vals):ax.text(b.get_x()+b.get_width()/2,v+1,f'{v:.1f}%' if v%1 else f'{v:.0f}%',ha='center',va='bottom')
    ax.set_ylim(0,max(vals)*1.26);ax.set_ylabel('Pre-period-equivalent candidate scale (%)')
    ax.set_title('All selected candidates' if group=='all' else 'Excluding 29 key-dependent cases')
fig,ax=plt.subplots(figsize=(7.5,5));panel(ax,'all')
fig.text(.02,.015,'Simulation bars: abrupt target daily intensity at first tested dose with recovery ≥80%.\nMissing cells receive no additions. Recorded turnover is not illicit flow.\nTested-grid brackets are not confidence intervals.',fontsize=9);fig.tight_layout(rect=[0,.15,1,1])
for ext in ['png','pdf','svg']:fig.savefig(FIG/f'Figure4_regenerated.{ext}',dpi=220)
plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(11,5));panel(axs[0],'all');panel(axs[1],'exclude_cases')
fig.text(.02,.015,'Each panel uses its own candidate denominator; simulation bars show target daily intensity.\nCentered frozen-150 calibration; 2,500 repetitions. Missing cells receive no additions.',fontsize=9);fig.tight_layout(rect=[0,.10,1,1])
for ext in ['png','pdf','svg']:fig.savefig(FIG/f'FigureS3_1_regenerated.{ext}',dpi=220)
plt.close(fig)
r=pd.read_csv(OUT/'FINAL_RESULTS.csv');r.query('scale=="equal_cumulative" and calibration=="frozen150_centered"').to_csv(OUT/'EQUAL_CUMULATIVE_RESULTS.csv',index=False)
pd.read_csv(ROOT/'tables/empirical_response_shapes.csv').query('candidate_group in ["all","exclude_cases"]').to_csv(OUT/'EMPIRICAL_RESPONSE_SPECIFICATIONS.csv',index=False)
p=pd.read_parquet(ROOT/'historical/full_zip_panel_vectorized.parquet')
defs=pd.read_csv(ROOT/'revision/container_definitions.csv');cases=set(defs[defs.key_dependent_case].item_id)
win=p[p.day.between(pd.Timestamp('2019-10-07',tz='UTC'),pd.Timestamp('2019-11-17',tz='UTC'))];vol=[]
for label,mask in [('all_candidates',win.whole_word_arm=='substitute'),('exclude_29_cases',(win.whole_word_arm=='substitute')&~win.item_id.isin(cases)),('29_cases_only',win.item_id.isin(cases)),('full_archive_controls',win.whole_word_arm=='control')]:
    d=win[mask];pre=float(d[d.day<pd.Timestamp('2019-10-28',tz='UTC')].units.sum());post=float(d[d.day>=pd.Timestamp('2019-10-28',tz='UTC')].units.sum())
    vol.append(dict(group=label,pre_units=pre,post_units=post,change_fraction=post/pre-1,window='2019-10-07 through 2019-11-17',pre_days=21,post_days=21))
pd.DataFrame(vol).to_csv(OUT/'MATCHED_AGGREGATE_VOLUMES.csv',index=False)
# Market-only components of Figures 2/3 are available; normalization requires a separate player export.
rows=[]
for name,mask in [('substring_keys',p.arm=='key'),('whole_word_keys',p.whole_word_arm=='key'),('candidates',p.arm=='substitute')]:
    q=p[mask & (p.day<'2022-01-01')].copy();weekly=q.groupby(pd.Grouper(key='day',freq='W-SUN')).units.sum()
    rows.extend({'week_ending_UTC':str(date.date()),'series':name,'recorded_units':u} for date,u in weekly.items())
pd.DataFrame(rows).to_csv(FIG/'Figures2_3_market_components_only.csv',index=False)
(FIG/'COVERAGE.json').write_text(json.dumps({'Figure1':'Conceptual figure; not regenerated by statistical code','Figure2':'Market components regenerated; SteamDB player source absent; full figure not regenerated','Figure3':'Market components regenerated; SteamDB player source absent; player-normalized series not regenerated','Figure4':'Data and replacement PNG/PDF/SVG regenerated; layout is newly drawn, not pixel reproduction','FigureS3_1':'Data and replacement PNG/PDF/SVG regenerated','Graphical_abstract':'Numerical data regenerated; conceptual design not redrawn'},indent=2),encoding='utf-8')
print('FIGURES_AND_SUPPLEMENT_TABLES_COMPLETE',flush=True)
